        NCDSP3HeaderAddMODIFIED_JULIAN_DAY_START(builder, self.MODIFIED_JULIAN_DAY_START)
        NCDSP3HeaderAddFRACTIONAL_DAY(builder, self.FRACTIONAL_DAY)
        NCDSP3HeaderAddEPOCH_INTERVAL_SECONDS(builder, self.EPOCH_INTERVAL_SECONDS)
        NCDSP3HeaderAddNUMBER_OF_EPOCHS(builder, self.NUMBER_OF_EPOCHS)
        if self.SATELLITE_IDS is not None:
            NCDSP3HeaderAddSATELLITE_IDS(builder, SATELLITE_IDS)
        if self.SATELLITE_ACCURACY_EXPONENTS is not None:
            NCDSP3HeaderAddSATELLITE_ACCURACY_EXPONENTS(builder, SATELLITE_ACCURACY_EXPONENTS)
        NCDSP3HeaderAddPOSITION_VELOCITY_BASE(builder, self.POSITION_VELOCITY_BASE)
        NCDSP3HeaderAddCLOCK_RATE_BASE(builder, self.CLOCK_RATE_BASE)
        if self.COMMENT is not None:
            NCDSP3HeaderAddCOMMENT(builder, COMMENT)
        NCDSP3Header = NCDSP3HeaderEnd(builder)
        return NCDSP3Header
